use std::collections::HashMap;
use std::path::Path;
use std::sync::Arc;

use crate::error::{AstError, Result};
use crate::model::{ParseContext, ParseOptions, ParsedFile};
use crate::traits::LanguageParser;

const GENERATED_MARKERS: &[&str] = &[
    "@generated",
    "DO NOT EDIT",
    "Code generated by",
    "Automatically generated",
    "Autogenerated by",
    "This file is generated",
    "GENERATED BY PROTO-GEN",
    "<auto-generated>",
];

/// Registry and dispatcher for multi-language AST parsers.
pub struct AstRegistry {
    parsers_by_ext: HashMap<String, Arc<dyn LanguageParser>>,
    parsers_by_name: HashMap<String, Arc<dyn LanguageParser>>,
    parsers_by_id: HashMap<String, Arc<dyn LanguageParser>>,
}

impl Default for AstRegistry {
    fn default() -> Self {
        Self::new()
    }
}

impl AstRegistry {
    /// Create an empty registry
    pub fn new() -> Self {
        Self {
            parsers_by_ext: HashMap::new(),
            parsers_by_name: HashMap::new(),
            parsers_by_id: HashMap::new(),
        }
    }

    /// Register a language parser implementation
    pub fn register(&mut self, parser: Arc<dyn LanguageParser>) {
        let id = parser.language_id().to_string();

        for ext in parser.file_extensions() {
            self.parsers_by_ext
                .insert(ext.to_lowercase(), Arc::clone(&parser));
        }

        for filename in parser.special_filenames() {
            self.parsers_by_name
                .insert(filename.to_string(), Arc::clone(&parser));
        }

        self.parsers_by_id.insert(id, parser);
    }

    /// Create standard registry with all compiled language parsers
    pub fn standard() -> Self {
        let mut registry = Self::new();
        #[cfg(feature = "python")]
        registry.register(Arc::new(crate::languages::python::PythonParser::new()));
        #[cfg(feature = "typescript")]
        {
            registry.register(Arc::new(crate::languages::typescript::TypeScriptParser::typescript()));
            registry.register(Arc::new(crate::languages::typescript::TypeScriptParser::tsx()));
        }
        #[cfg(feature = "ruby")]
        registry.register(Arc::new(crate::languages::ruby::RubyParser::new()));
        #[cfg(feature = "rust")]
        registry.register(Arc::new(crate::languages::rust::RustParser::new()));
        #[cfg(feature = "go")]
        registry.register(Arc::new(crate::languages::go::GoParser::new()));
        #[cfg(feature = "sql")]
        registry.register(Arc::new(crate::languages::sql::SqlParser::new()));
        #[cfg(feature = "doc")]
        registry.register(Arc::new(crate::languages::doc::MarkdownParser::new()));
        registry
    }

    /// Check if a file's content or filename indicates generated code
    pub fn is_generated_content(filepath: &str, content: &str) -> bool {
        let path = Path::new(filepath);
        if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
            if name.ends_with(".min.js")
                || name.ends_with(".min.css")
                || name.ends_with(".pb.go")
                || name.ends_with("_pb2.py")
                || name.ends_with(".d.ts.map")
            {
                return true;
            }
        }

        for line in content.lines().take(15) {
            let trimmed = line.trim();
            for marker in GENERATED_MARKERS {
                if trimmed.contains(marker) {
                    return true;
                }
            }
        }

        false
    }

    /// Resolve parser for a given file path and content
    pub fn resolve_parser(&self, path: &Path, content: &str) -> Result<Arc<dyn LanguageParser>> {
        // 1. Exact special filename check (e.g. routes.rb, Gemfile)
        if let Some(filename) = path.file_name().and_then(|f| f.to_str()) {
            if let Some(p) = self.parsers_by_name.get(filename) {
                return Ok(Arc::clone(p));
            }
        }

        // 2. Extension check (.py, .ts, .tsx, .rb, etc.)
        if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
            if let Some(p) = self.parsers_by_ext.get(&ext.to_lowercase()) {
                return Ok(Arc::clone(p));
            }
        }

        // 3. Shebang check (#!/usr/bin/env python3)
        if content.starts_with("#!") {
            if let Some(first_line) = content.lines().next() {
                if first_line.contains("python") {
                    if let Some(p) = self.parsers_by_id.get("python") {
                        return Ok(Arc::clone(p));
                    }
                } else if first_line.contains("ruby") {
                    if let Some(p) = self.parsers_by_id.get("ruby") {
                        return Ok(Arc::clone(p));
                    }
                } else if first_line.contains("node") || first_line.contains("deno") {
                    if let Some(p) = self.parsers_by_id.get("javascript")
                        .or_else(|| self.parsers_by_id.get("typescript"))
                    {
                        return Ok(Arc::clone(p));
                    }
                }
            }
        }

        Err(AstError::UnsupportedLanguage(format!(
            "No registered parser for file '{}'",
            path.display()
        )))
    }

    /// Parse a source file into a `ParsedFile` AST graph representation
    pub fn parse_file(
        &self,
        filepath: &str,
        content: &str,
        options: Option<ParseOptions>,
    ) -> Result<ParsedFile> {
        let opts = options.unwrap_or_default();
        let is_generated = Self::is_generated_content(filepath, content);

        if is_generated && opts.skip_generated {
            return Ok(ParsedFile {
                filepath: filepath.to_string(),
                language: "unknown".to_string(),
                is_generated: true,
                nodes: Vec::new(),
                edges: Vec::new(),
                unresolved_references: Vec::new(),
                diagnostics: Vec::new(),
            });
        }

        let path = Path::new(filepath);
        let parser = self.resolve_parser(path, content)?;

        let ctx = ParseContext {
            filepath,
            content,
            options: opts,
        };

        let mut parsed = parser.parse(&ctx)?;
        parsed.is_generated = is_generated;
        Ok(parsed)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_generated_content() {
        assert!(AstRegistry::is_generated_content(
            "foo.go",
            "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage foo"
        ));
        assert!(AstRegistry::is_generated_content(
            "bundle.min.js",
            "function(){}"
        ));
        assert!(AstRegistry::is_generated_content(
            "model.py",
            "# @generated\nclass Foo: pass"
        ));
        assert!(!AstRegistry::is_generated_content(
            "auth.py",
            "def login(): pass"
        ));
    }
}
